'use strict';
const A=window.ACADEMY, lessons=A.curriculum.lessons, stages=A.curriculum.stages;
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const KEY='ai-engineering-academy-v1';
const fresh=()=>({version:1,done:[],notes:{},quiz:{},bookmarks:[],gates:[]});
function validateState(x){if(!x||x.version!==1||!Array.isArray(x.done)||!Array.isArray(x.bookmarks)||!Array.isArray(x.gates)||typeof x.notes!=='object'||!x.notes||Array.isArray(x.notes)||typeof x.quiz!=='object'||!x.quiz||Array.isArray(x.quiz))throw Error('Unsupported progress file');return {version:1,done:[...new Set(x.done.filter(v=>lessons.some(l=>l.id===v)))],bookmarks:[...new Set(x.bookmarks.filter(v=>A.resources.some(r=>r.id===v)))],gates:[...new Set(x.gates.filter(v=>stages.some(s=>s.id===v)))],notes:Object.fromEntries(Object.entries(x.notes).filter(([k,v])=>Object.prototype.hasOwnProperty.call(A.documents,k)&&typeof v==='string')),quiz:Object.fromEntries(Object.entries(x.quiz).filter(([k,v])=>lessons.some(l=>l.id===k&&Number.isInteger(v)&&v>=0&&v<l.quiz.options.length)))};}
function mergeProgress(current,imported){const notes={...current.notes};let conflicts=0;for(const [path,value] of Object.entries(imported.notes)){if(!notes[path]?.trim())notes[path]=value;else if(value.trim()&&notes[path]!==value){const appendix='\n\n--- Imported backup ---\n'+value;if(!notes[path].includes(appendix)){notes[path]+=appendix;conflicts++;}}}return {state:{version:1,done:[...new Set([...current.done,...imported.done])],bookmarks:[...new Set([...current.bookmarks,...imported.bookmarks])],gates:[...new Set([...current.gates,...imported.gates])],notes,quiz:{...imported.quiz,...current.quiz}},conflicts};}
let state=fresh();try{const raw=localStorage.getItem(KEY);if(raw)state=validateState(JSON.parse(raw));}catch{}
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));return true;}catch{toast('Device storage is unavailable. Export progress to keep a backup.');return false;}}
let toastTimer;function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').style.display='none',4000);}
const done=id=>state.done.includes(id), stageLessons=id=>lessons.filter(l=>l.stage===Number(id));
const docs=prefix=>Object.entries(A.documents).filter(([p])=>p.startsWith(prefix));
const linkDoc=(p,anchor='')=>'#doc='+encodeURIComponent(p)+(anchor?'&section='+encodeURIComponent(anchor):'');
const knownAssets=new Set(A.assets||['content/resources.json','content/labs/solutions/reference.py']);
const navItems=[['overview','◫','Overview'],['path','⌁','Learning path'],['labs','⌘','Practice labs'],['library','▤','Resource library'],['manuals','▧','Field manuals'],['capstones','◇','Capstones'],['workbench','⚙','Harness sandbox'],['progress','↗','My progress']];
function nav(section){$('#nav').innerHTML=navItems.map(([id,icon,label])=>`<a href="#${id}" class="${section===id?'active':''}"><span class="icon">${icon}</span>${label}${id==='path'?'<span class="nav-count">24</span>':''}</a>`).join('');$('#section-name').textContent=navItems.find(x=>x[0]===section)?.[2]||'Lesson';}
function title(k,t,p){return `<div class="page-title"><span class="eyebrow">${k}</span><h1>${t}</h1><p>${p}</p></div>`;}
function stageCard(s){let ls=stageLessons(s.id),n=ls.filter(l=>done(l.id)).length;return `<a class="stage-card" href="#stage=${s.id}"><div class="stage-top"><span class="stage-id">${String(s.id).padStart(2,'0')}</span><span class="tag">${n===ls.length?'Completed':s.id<3?'Foundation':s.id<6?'Builder':'Advanced'}</span></div><h3>${esc(s.title)}</h3><p>${esc(s.description)}</p><div class="card-bottom"><span>${ls.length} lessons · ${ls.reduce((v,l)=>v+l.exerciseCount,0)} exercises</span><span>${n}/${ls.length} ↗</span></div><div class="progress-track"><div class="progress-fill" style="width:${n/ls.length*100}%"></div></div></a>`;}
function overview(){const next=lessons.find(l=>!done(l.id))||lessons[0];return `<section class="hero"><div><span class="eyebrow">Your next chapter starts here</span><h1>Build with AI.<br><em>Engineer what lasts.</em></h1><p>A hands-on path from better prompts to reliable agents. Learn the systems behind the magic, one experiment at a time.</p><div class="actions"><a class="btn" href="#lesson=${next.id}">${state.done.length?'Continue learning':'Start learning'} <span>↗</span></a><a class="btn secondary" href="${linkDoc('docs/START-HERE.md')}">Read the field guide</a></div></div><div class="hero-art" aria-hidden="true"><div class="orb"></div><div class="core">ai</div><span class="orbit-label one">01 / CONTEXT</span><span class="orbit-label two">02 / TOOLS + SKILLS</span><span class="orbit-label three">03 / HARNESS</span></div></section><div class="stats"><div class="stat"><strong>${stages.length}</strong><span>progressive stages</span></div><div class="stat"><strong>${lessons.length}</strong><span>original lessons</span></div><div class="stat"><strong>${lessons.reduce((s,l)=>s+l.exerciseCount,0)}</strong><span>lesson exercises</span></div><div class="stat"><strong>${A.resources.length}</strong><span>curated resources</span></div></div><section class="continue"><div class="round-num">${next.id}</div><div class="continue-info"><span class="eyebrow">${state.done.length?'Pick up where you left off':'Your first mission'}</span><h3>${esc(next.title)}</h3><p>Stage ${next.stage} · ${next.minutes} min estimate · Learn, build, reflect</p></div><a href="#lesson=${next.id}" class="btn small">Open lesson →</a></section><div class="section-head"><h2>The learning path</h2><a href="#path">Explore all stages ↗</a></div><div class="grid">${stages.map(stageCard).join('')}</div><div class="lower-grid"><div class="dark-card"><span class="eyebrow">One case study. Real engineering decisions.</span><h2>Meet Signal Desk.</h2><p>Build a support and QA agent, then learn to break it, measure it, and make it reliable. The reference lab runs entirely offline.</p><code>python3 -m lab.cli demo</code></div><div class="plain-card"><span class="eyebrow">Made for your next step</span><h3>Turn learning into evidence.</h3><p>Capture experiments, earn your own stage gates, and finish with a capstone you can defend.</p><a href="#capstones">Choose your capstone ↗</a></div></div>`;}
function lessonRow(l){return `<a class="lesson-row" href="#lesson=${l.id}"><span class="num">${done(l.id)?'✓':l.id}</span><div class="info"><h3>${esc(l.title)}</h3><p>${esc(l.summary)}</p></div><span class="meta">${l.minutes} min<br>${l.exerciseCount} exercises ↗</span></a>`;}
function learningPath(){return title('The curriculum','From operator to engineer.','Eight stages that build on each other. Take the diagnostic if you already have experience; prove the stage gates before skipping ahead.')+`<div class="actions"><a class="btn secondary small" href="${linkDoc('docs/START-HERE.md')}">Take the diagnostic</a><a class="btn secondary small" href="${linkDoc('docs/ASSESSMENT.md')}">Assessment rubric</a></div>`+stages.map(s=>`<div class="section-head"><h2>${s.id.toString().padStart(2,'0')} · ${esc(s.title)}</h2><span class="tag">${stageLessons(s.id).filter(l=>done(l.id)).length}/3 complete</span></div><p>${esc(s.outcome||s.description)}</p><div class="lesson-list">${stageLessons(s.id).map(lessonRow).join('')}</div>`).join('');}
function stage(id){const s=stages.find(s=>s.id===Number(id));if(!s)return missing();return `<a class="back" href="#path">← All stages</a>`+title(`Stage ${s.id} of 8`,esc(s.title),esc(s.description))+`<div class="notice"><strong>What you will produce:</strong> ${esc(s.outcome)}</div><div class="lesson-list">${stageLessons(s.id).map(lessonRow).join('')}</div><div class="section-head"><h2>Explore this stage</h2><a href="#library?stage=${s.id}">Readings and courses ↗</a></div><a class="btn secondary" href="${linkDoc('docs/ASSESSMENT.md')}">Review the stage gate</a>`;}
function resolveHref(url,path){if(/^https?:\/\//.test(url))return url;if(/^[a-z][a-z0-9+.-]*:/i.test(url)||url.startsWith('//')||url.startsWith('/'))return '#';const split=url.indexOf('#'),file=split<0?url:url.slice(0,split);let anchor=split<0?'':url.slice(split+1);try{anchor=decodeURIComponent(anchor);}catch{return '#';}const bits=file?path.split('/').slice(0,-1):path.split('/');for(const v of file.split('/')){if(v==='..'){if(!bits.length)return '#';bits.pop();}else if(v!=='.'&&v)bits.push(v);}const target=bits.join('/');if(Object.prototype.hasOwnProperty.call(A.documents,target))return linkDoc(target,anchor);if(knownAssets.has(target))return target;return '#';}
function headingSlug(text){return text.replace(/\[([^\]]+)\]\([^)]+\)/g,'$1').replace(/[`*_]/g,'').trim().toLowerCase().replace(/[^\p{L}\p{N}\s_-]/gu,'').replace(/\s/g,'-');}
function inline(text,path){let slots=[];const hold=html=>`\u0000${slots.push(html)-1}\u0000`;let s=text.replace(/`([^`]+)`/g,(_,v)=>hold(`<code>${esc(v)}</code>`));s=s.replace(/\[([^\]]+)\]\(([^)]+)\)/g,(_,label,url)=>hold(`<a href="${esc(resolveHref(url,path))}" ${/^https?:/.test(url)?'target="_blank" rel="noopener noreferrer"':''}>${esc(label)}</a>`));s=esc(s).replace(/\*\*([^*]+)\*\*/g,'<strong>$1</strong>').replace(/\*([^*\n]+)\*/g,'<em>$1</em>');return s.replace(/\u0000(\d+)\u0000/g,(_,n)=>slots[Number(n)]);}
function markdown(src,path){let lines=src.split('\n'),out=[],list=null,para=[],code=null,block=[],detail=false;const headings=new Map();function flush(){if(para.length){out.push(`<p>${inline(para.join(' '),path)}</p>`);para=[];}if(list){out.push(`</${list}>`);list=null;}}
 for(let i=0;i<lines.length;i++){let l=lines[i];if(l.startsWith('```')){flush();if(code!==null){out.push(`<pre><code>${esc(block.join('\n'))}</code></pre>`);code=null;block=[];}else code=l.slice(3);continue;}if(code!==null){block.push(l);continue;}if(/^\s*\|/.test(l)&&i+1<lines.length&&/^\s*\|?\s*:?-{3}/.test(lines[i+1])){flush();const cells=v=>v.trim().replace(/^\||\|$/g,'').split('|').map(v=>v.trim());out.push('<div class="table-wrap"><table><thead><tr>'+cells(l).map(v=>`<th>${inline(v,path)}</th>`).join('')+'</tr></thead><tbody>');i+=2;while(i<lines.length&&/^\s*\|/.test(lines[i])){out.push('<tr>'+cells(lines[i]).map(v=>`<td>${inline(v,path)}</td>`).join('')+'</tr>');i++;}i--;out.push('</tbody></table></div>');continue;}
 const h=l.match(/^(#{1,6})\s+(.+)/);if(h){flush();const slug=headingSlug(h[2]),count=headings.get(slug)||0,id=slug+(count?'-'+count:'');headings.set(slug,count+1);if(detail&&h[1].length<=2){out.push('</details>');detail=false;}if(h[1].length===2&&/hint|solution|answer key/i.test(h[2])){out.push(`<details id="${esc(id)}"><summary>${inline(h[2],path)} — reveal after your attempt</summary>`);detail=true;}else out.push(`<h${h[1].length} id="${esc(id)}">${inline(h[2],path)}</h${h[1].length}>`);continue;}
 const li=l.match(/^\s*(?:[-*]|\d+\.)\s+(.+)/);if(li){if(para.length){out.push(`<p>${inline(para.join(' '),path)}</p>`);para=[];}let kind=/^\s*\d+\./.test(l)?'ol':'ul';if(list!==kind){if(list)out.push(`</${list}>`);out.push(`<${kind}>`);list=kind;}out.push(`<li>${inline(li[1],path)}</li>`);continue;}if(!l.trim()){flush();continue;}if(/^---+$/.test(l)){flush();out.push('<hr>');continue;}if(l.startsWith('> ')){flush();out.push(`<blockquote>${inline(l.slice(2),path)}</blockquote>`);continue;}if(list){out.push(`</${list}>`);list=null;}para.push(l);}
 flush();if(code!==null)out.push(`<pre><code>${esc(block.join('\n'))}</code></pre>`);if(detail)out.push('</details>');return out.join('\n');}
function quizHTML(l){let q=l.quiz,selected=state.quiz[l.id];return `<div class="side-block"><h3>Check your understanding</h3><p>${esc(q.question)}</p>${q.options.map((o,i)=>`<button class="quiz-option ${selected===i?'selected':''}" data-answer="${i}" data-lesson="${l.id}">${esc(o)}</button>`).join('')}${selected!==undefined?`<div class="quiz-feedback"><strong>${selected===q.answer?'Correct.':'Try again.'}</strong> ${esc(q.explanation)}</div>`:''}</div>`;}
function readDoc(path,l){const d=Object.prototype.hasOwnProperty.call(A.documents,path)?A.documents[path]:null;if(!d)return missing();return `<a class="back" href="${l?'#stage='+l.stage:'#manuals'}">← ${l?'Stage '+l.stage:'Field manuals'}</a><div class="reading-layout"><article class="reading">${markdown(d.text,path)}</article><aside class="reading-side">${l?`<div class="side-block"><span class="eyebrow">Lesson ${l.id} · ${l.minutes} min</span><h3>What you will practice</h3><ul>${l.objectives.map(o=>`<li>${esc(o)}</li>`).join('')}</ul><button class="btn" id="mark-done" data-id="${l.id}">${done(l.id)?'✓ Completed · undo':'Mark lesson complete'}</button><a class="btn secondary" href="#lesson=${lessons[(lessons.indexOf(l)+1)%lessons.length].id}">Next lesson →</a></div>${quizHTML(l)}`:`<div class="side-block"><span class="eyebrow">Keep a working copy</span><p>Read, adapt, and save evidence of your work. The source files are included in the project archive.</p><button class="btn secondary" id="download-doc" data-path="${esc(path)}">Download Markdown ↓</button></div>`}<div class="side-block"><h3>Your experiment notes</h3><p>Prediction → observation → next change. Saved only in this browser.</p><textarea id="notes" data-path="${esc(path)}" aria-label="Your experiment notes" placeholder="What did you try? What did the evidence show?">${esc(state.notes[path]||'')}</textarea><span id="note-status" class="results-count" aria-live="polite"></span></div><div class="side-block"><h3>Use a tutor wisely</h3><p>Try first. Ask for one hint. Explain your reasoning before revealing a solution.</p><a href="${linkDoc('templates/tutor-prompt.md')}">Open the tutor prompt ↗</a></div></aside></div>`;}
function docCards(entries,label){return `<div class="grid">${entries.map(([p,d])=>`<a class="doc-card" href="${linkDoc(p)}"><span class="eyebrow">${label}</span><h3>${esc(d.title)}</h3><p>${esc(d.text.split('\n\n').find(v=>!v.startsWith('#'))?.slice(0,155)||'Practical guidance and reusable evidence requirements.')}…</p><div class="card-bottom"><span>${Math.max(1,Math.ceil((d.words||100)/220))} min reading estimate</span><span>Open ↗</span></div></a>`).join('')}</div>`;}
function manuals(){return title('Read. Adapt. Apply.','Your field library.','Original articles, learner manuals, reusable engineering templates, and a portable course book.')+`<div class="actions"><a class="btn" href="fieldbook.pdf" download>Download the fieldbook ↓</a><a class="btn secondary" href="academy-source.zip" download>Download full project ↓</a></div><div class="section-head"><h2>Learner manuals</h2></div>`+docCards(docs('docs/'),'Manual')+`<div class="section-head"><h2>Original articles</h2></div>`+docCards(docs('content/articles/'),'Article')+`<div class="section-head"><h2>Templates to make your own</h2></div>`+docCards(docs('templates/'),'Template')+`<div class="section-head"><h2>Reading pathways</h2></div>`+docCards(docs('content/library/'),'Reading guide')+`<div class="section-head"><h2>Executable workflow guides</h2></div>`+docCards(docs('lab/').filter(([p])=>p.split('/').length===2),'Code guide')+`<div class="section-head"><h2>Research and development fixtures</h2></div>`+docCards([...docs('content/research/'),...docs('content/dev-sandbox/')],'Practice fixture');}
function labs(){let entries=docs('content/labs/').filter(([p])=>/^content\/labs\/\d{2}-[^/]+\.md$/.test(p));return title('The practice ground','Build. Break. Understand.',`${entries.length} practical labs: component exercises, real MCP, installed skills, and a complete student harness. Run them locally; this portal tracks your learning.`)+`<div class="dark-card"><span class="eyebrow">Run your first experiment</span><code>python3 -m lab.cli demo</code><p>Then inspect the trace and compare it with your prediction.</p><a href="${linkDoc('lab/README.md')}">Open the executable lab manual ↗</a></div><div class="actions"><a class="btn secondary" href="${linkDoc('docs/INTEGRATION-LABS.md')}">Follow the integration route ↗</a><a class="btn secondary" href="#workbench">Try the concept simulator ↗</a></div><div class="section-head"><h2>Your lab assignments</h2></div>`+docCards(entries,'Practice lab');}
let libraryQuery='',libraryType='',libraryStage='',savedOnly=false;
function resourceCards(){let rs=A.resources.filter(r=>(!libraryQuery||[r.title,r.provider,r.why,r.practice].join(' ').toLowerCase().includes(libraryQuery.toLowerCase()))&&(!libraryType||r.type===libraryType)&&(!libraryStage||String(r.stage)===libraryStage)&&(!savedOnly||state.bookmarks.includes(r.id)));$('#resource-results').innerHTML=`<div class="results-count">${rs.length} resources · checked October 2026 · access terms may change</div><div class="grid">${rs.map(r=>`<article class="resource"><div><button class="save" data-save="${esc(r.id)}" aria-label="${state.bookmarks.includes(r.id)?'Unsave':'Save'} ${esc(r.title)}" aria-pressed="${state.bookmarks.includes(r.id)}">${state.bookmarks.includes(r.id)?'★':'☆'}</button><span class="eyebrow">${esc(r.provider)} / ${esc(r.type)}</span></div><h3>${esc(r.title)}</h3><p>${esc(r.why)}</p><div><span class="tag">Stage ${r.stage}</span> <span class="tag">${esc(r.access)}</span></div><p class="task"><strong>Put it into practice:</strong> ${esc(r.practice)}</p><a href="${esc(r.url)}" target="_blank" rel="noopener noreferrer">Open resource ↗</a><p>${esc(r.verification||'')}${r.accessNotes?' '+esc(r.accessNotes):''}</p></article>`).join('')}</div>${!rs.length?'<div class="empty">No matching resources. Clear a filter or try a broader search.</div>':''}`;}
function library(){return title('A curated reading room','Good sources. Better practice.','Courses from Claude Academy and Hugging Face, primary documentation, books, and videos. Each resource has a concrete follow-up task.')+`<div class="filters"><input id="resource-search" type="search" aria-label="Search resources" placeholder="Search topics, providers, or titles…" value="${esc(libraryQuery)}"><select id="resource-type" aria-label="Resource type"><option value="">All formats</option>${[...new Set(A.resources.map(r=>r.type))].sort().map(t=>`<option ${libraryType===t?'selected':''}>${esc(t)}</option>`).join('')}</select><select id="resource-stage" aria-label="Resource stage"><option value="">All stages</option>${stages.map(s=>`<option value="${s.id}" ${libraryStage===String(s.id)?'selected':''}>Stage ${s.id}</option>`).join('')}</select><button class="btn secondary" id="saved-only" aria-pressed="${savedOnly}">${savedOnly?'★ Saved only':'☆ Show saved'}</button></div><div id="resource-results"></div>`;}
function capstones(){return title('Make the work your own','Build something worth defending.','Choose one substantial project. Finish with a working system, a frozen evaluation, an incident exercise, and an evidence-based defense.')+docCards(docs('capstones/'),'Capstone brief')+`<div class="section-head"><h2>Release with evidence</h2></div><div class="plain-card"><p>Use the shared rubric. A capstone is complete when another person can reproduce your result and challenge its limits.</p><a class="btn secondary" href="${linkDoc('docs/ASSESSMENT.md')}">Open the assessment manual</a></div>`;}
function progress(){return title('Evidence over completion ticks','Your progress, your proof.','Lesson completion is self-reported. Knowledge checks and notes help you reflect; stage gates require the artifacts in the assessment manual.')+`<div class="stats"><div class="stat"><strong>${state.done.length}/${lessons.length}</strong><span>lessons completed</span></div><div class="stat"><strong>${lessons.filter(l=>state.quiz[l.id]===l.quiz.answer).length}</strong><span>knowledge checks passed</span></div><div class="stat"><strong>${Object.values(state.notes).filter(x=>x.trim()).length}</strong><span>documents with notes</span></div><div class="stat"><strong>${state.gates.length}/8</strong><span>self-assessed stage gates</span></div></div><div class="notice">Back up your progress with Export in the sidebar. Local and hosted versions use separate browser storage; import your JSON to transfer it.</div><div class="checklist">${stages.map(s=>`<label><input type="checkbox" data-gate="${s.id}" ${state.gates.includes(s.id)?'checked':''}><span>I have reviewed the evidence for stage ${s.id}: <strong>${esc(s.title)}</strong></span></label>`).join('')}</div><div class="section-head"><h2>Your lesson record</h2><a href="${linkDoc('docs/ASSESSMENT.md')}">Read the rubric ↗</a></div><div class="lesson-list">${lessons.map(lessonRow).join('')}</div>`;}
function workbench(){return title('Interactive concept lab','See the harness at work.','Change the input and action budget. Step through how a small runtime can control a proposed tool call.')+`<div class="notice">This is a deterministic teaching simulator. It does not call an AI model or execute the Python harness. Use the runnable labs to inspect the real reference implementation.</div><div class="workbench"><div class="plain-card"><h3>Configure an experiment</h3><p>Predict the final outcome before running.</p><label for="scenario">Scenario</label><select id="scenario"><option value="normal">Normal ticket → draft reply</option><option value="injection">Ticket asks to export customer data</option><option value="timeout">Policy lookup times out once</option><option value="duplicate">Duplicate draft request</option></select><label for="budget">Maximum tool attempts (1-8)</label><input id="budget" type="number" min="1" max="8" value="4"><div class="actions"><button class="btn" id="sim-run">Run experiment →</button></div><p style="margin-top:20px">Observe the distinction between a model proposal, a permitted action, and a completed side effect.</p></div><div><div id="trace" class="trace" role="log" aria-live="polite">Ready. Choose a scenario, predict the outcome, then run.</div><p class="results-count">The action budget is per attempted tool call. An idempotent replay spends a call but creates no new draft.</p></div></div><div class="section-head"><h2>Take it into code</h2></div><a class="btn secondary" href="${linkDoc('lab/README.md')}">Open the Python harness manual ↗</a>`;}
function simulate(){let kind=$('#scenario').value,b=Number($('#budget').value);if(!Number.isInteger(b)||b<1||b>8){toast('Choose a whole number between 1 and 8.');return;}let lines=['START · isolated synthetic ticket',`BUDGET · ${b} attempted tool calls`],used=0,drafts=0;function call(name,fn){if(used>=b){lines.push('STOP · action budget exhausted before dispatch');return false;}used++;lines.push(`${used}. PROPOSE · ${name}`);fn();return true;}if(kind==='injection'){call('export_customer_database',()=>lines.push('DENY · tool absent from capability allowlist'));lines.push('HANDOFF · untrusted ticket cannot grant permissions');}else{let ready=true;if(kind==='timeout')ready=call('lookup_policy',()=>lines.push('ERROR · transient timeout; one bounded retry allowed'));if(ready)ready=call('lookup_policy',()=>lines.push('ALLOW · read-only tool → policy P-01'));if(ready)ready=call('save_draft [key: SD-demo-v1]',()=>{drafts++;lines.push('ALLOW · validated draft saved as D-001');});if(ready&&kind==='duplicate')call('save_draft [key: SD-demo-v1]',()=>lines.push('REPLAY · D-001 returned; no second side effect'));}lines.push(`END · ${used} calls used · ${drafts} drafts created`);$('#trace').textContent=lines.join('\n');}
function missing(){return title('Page unavailable','That page is not in this edition.','Return to the learning path to choose an available lesson.')+'<a class="btn" href="#path">Open learning path</a>';}
function download(name,data,type){const url=URL.createObjectURL(new Blob([data],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function parseRoute(raw){try{const split=raw.indexOf('&section=');return {route:decodeURIComponent(split<0?raw:raw.slice(0,split)),anchor:split<0?'':decodeURIComponent(raw.slice(split+9))};}catch{return {route:'unavailable',anchor:''};}}
function render(){const parsed=parseRoute(location.hash.slice(1)||'overview');const [route,query]=parsed.route.split('?');let html,section=route;if(route.startsWith('lesson=')){section='path';const l=lessons.find(l=>l.id===route.slice(7));html=l?readDoc(l.file,l):missing();}else if(route.startsWith('stage=')){section='path';html=stage(route.slice(6));}else if(route.startsWith('doc=')){section='manuals';html=readDoc(route.slice(4));}else {if(route==='library'&&query)libraryStage=new URLSearchParams(query).get('stage')||'';const pages={overview,path:learningPath,labs,library,manuals,capstones,progress,workbench};html=(Object.prototype.hasOwnProperty.call(pages,route)?pages[route]:missing)();}nav(section);$('#main').innerHTML=html;if(route==='library')resourceCards();document.title=(route.startsWith('lesson=')?lessons.find(l=>l.id===route.slice(7))?.title:route.startsWith('doc=')?A.documents[route.slice(4)]?.title:$('#section-name').textContent)+' · AI Engineering Academy';window.scrollTo(0,0);const target=parsed.anchor?document.getElementById(parsed.anchor):null;if(target?.closest('.reading')){let detail=target.closest('details');while(detail){detail.open=true;detail=detail.parentElement?.closest('details');}target.tabIndex=-1;target.focus({preventScroll:true});target.scrollIntoView();}else $('#main').focus({preventScroll:true});}
document.addEventListener('click',e=>{if(e.target.closest('.skip')){e.preventDefault();$('#main').focus();return;}const b=e.target.closest('button');if(!b)return;if(b.id==='import-progress')$('#import').click();if(b.id==='mark-done'){const id=b.dataset.id;state.done=done(id)?state.done.filter(x=>x!==id):[...state.done,id];save();b.textContent=done(id)?'✓ Completed · undo':'Mark lesson complete';toast(done(id)?'Lesson marked complete. Keep your evidence.':'Lesson reopened.');}if(b.dataset.answer!==undefined){const l=lessons.find(l=>l.id===b.dataset.lesson);state.quiz[l.id]=Number(b.dataset.answer);save();b.closest('.side-block').outerHTML=quizHTML(l);}if(b.dataset.save){const id=b.dataset.save;state.bookmarks=state.bookmarks.includes(id)?state.bookmarks.filter(x=>x!==id):[...state.bookmarks,id];save();resourceCards();}if(b.id==='saved-only'){savedOnly=!savedOnly;b.textContent=savedOnly?'★ Saved only':'☆ Show saved';b.setAttribute('aria-pressed',savedOnly);resourceCards();}if(b.id==='sim-run')simulate();if(b.id==='download-doc'){const p=b.dataset.path;download(p.split('/').pop(),A.documents[p].text,'text/markdown');}if(b.id==='export')download('academy-progress.json',JSON.stringify(state,null,2),'application/json');});
document.addEventListener('input',e=>{if(e.target.id==='notes'){state.notes[e.target.dataset.path]=e.target.value;const saved=save();$('#note-status').textContent=saved?'Saved on this device':'Not saved — export your progress';}if(e.target.id==='resource-search'){libraryQuery=e.target.value;resourceCards();}});
document.addEventListener('change',async e=>{let el=e.target;if(el.id==='resource-type'){libraryType=el.value;resourceCards();}if(el.id==='resource-stage'){libraryStage=el.value;resourceCards();}if(el.dataset.gate){const n=Number(el.dataset.gate);state.gates=el.checked?[...new Set([...state.gates,n])]:state.gates.filter(x=>x!==n);save();}if(el.id==='import'&&el.files[0]){try{if(el.files[0].size>5000000)throw Error('File is too large');let imported=validateState(JSON.parse(await el.files[0].text()));const merged=mergeProgress(state,imported);state=merged.state;const saved=save();render();toast('Progress merged. '+(merged.conflicts?'Conflicting notes were appended under Imported backup. ':'Existing notes and answers were preserved. ')+(saved?'':'Device storage failed; export a backup now.'));}catch(err){toast('Could not import: '+err.message);}el.value='';}});
window.addEventListener('hashchange',render);render();
